            }
        });
    if (!ctx.monitor_manager->loadOverrides(nullptr)) {
        LOG_WARNING(LogModule::SYSTEM, "runtime monitor overrides could not be loaded");
    }
    if (!ctx.monitor_manager->startConfigured()) {
        LOG_WARNING(LogModule::NETWORK,
                    "one or more monitor plugins failed to initialize or start");
    }

    // 启动历史数据持久化线程（非监控器，server.cpp 单独管理）
    if (ctx.db_mgr && ctx.db_mgr->isOpen()) {
        LOG_INFO(LogModule::SYSTEM, "starting history persistence thread (interval=5s)");
        start_history_persistence_thread(&ctx);
    }

    // 启动边缘遥测上报（可选，W-edge）。
    // 配置不完整/能力缺失时 start() 返回 false 并保持关闭，绝不半启用。
    //
    // 先构造配置事务（STABLE/TRIAL/ROLLBACK 状态机），再把它交给 exporter。
    // state_path 落在与 history.db 同一目录，崩溃后可由 hasCrashRecoveryFile
    // 检测到并触发 forceRollback。
    const std::string txn_state_path =
        resolveDatabasePath(ctx.cfg.data_dir.get())
            .substr(0, resolveDatabasePath(ctx.cfg.data_dir.get()).size() -
                            std::string("history.db").size()) +
        "config_txn_state";
    ctx.config_txn = std::make_shared<weaknet_dbus::ConfigTransaction>(txn_state_path);

    ctx.edge_exporter = std::make_unique<weaknet::EdgeTelemetryExporter>(
        ctx.cfg, /*hostname=*/"edge-node", ctx.config_txn);

    // 启动时若发现残留的 prior_values（上次 TRIAL 中崩溃），立即回滚还原。
    if (ctx.config_txn->hasCrashRecoveryFile()) {
        LOG_WARNING(LogModule::SYSTEM,
                    "检测到上次 TRIAL 中的崩溃残留，立即执行回滚还原: " << txn_state_path);
        ctx.config_txn->forceRollback(&ctx.cfg, "crash_recovery");
    }

    if (ctx.edge_exporter->start()) {
        LOG_INFO(LogModule::SYSTEM, "edge telemetry exporter started");

        // T3: 启动端侧 AI 异步初筛调度器（容量=1，并发=1，300s 冷却，15s SIGKILL 硬超时）
        ctx.edge_ai_scheduler = std::make_unique<weaknet::EdgeAiScheduler>(
            ctx.cfg.edge.device_id.get(),
            [&ctx](weaknet::EdgeAiHypothesisRecord hyp) {
                if (ctx.edge_exporter) {
                    ctx.edge_exporter->enqueueHypothesis(std::move(hyp));
                }
            });
        ctx.edge_ai_scheduler->start();
        LOG_INFO(LogModule::SYSTEM, "edge AI scheduler started (cooldown=300s, hard_timeout=15s)");
    }

    // 启动无线事实上行（Phase 4a，可选）。
    //
    // 与遥测上报**并列独立**：幂等域不同（event_id/incident_id vs
    // network_epoch+sequence_id），失败重发语义也不同，故各自线程与游标。
    // 数据源是 SQLite（跨重启延续的事实），因此必须等 db_mgr 已就绪。
    {
        const std::string uplink_state_path =
            resolveDatabasePath(ctx.cfg.data_dir.get())
                .substr(0, resolveDatabasePath(ctx.cfg.data_dir.get()).size() -
                                std::string("history.db").size()) +
            "wireless-uplink-state";
        if (ctx.db_mgr) {
            // 传 sampler 并在读侧持有共享锁：插件可被运行期 disable/restart，
            // 必须在读锁保护下安全采样，避免访问正被析构的监控器。
            ctx.wireless_uplink = std::make_unique<weaknet::EdgeWirelessUplinkExporter>(
                ctx.cfg, *ctx.db_mgr, uplink_state_path,
                [&ctx](std::vector<weaknet_dbus::ProcessNetInfo>* out) {
                    if (!out) return;
                    std::shared_lock<std::shared_mutex> lock(ctx.monitor_pointers_mutex);
                    if (ctx.process_net_profiler && ctx.process_net_profiler->isAvailable()) {
                        *out = ctx.process_net_profiler->getTopBandwidth(5);
                    }
                },
===DBUS-SAVE===
bool DbusService::handleSaveMonitorOverrides(DBusConnection* conn, DBusMessage* msg) {
    // 持久化运行时启停状态，影响后续启动行为：仅 root 可写。
    if (!requireRootCaller(conn, msg, "SaveMonitorOverrides")) return false;

    std::string error;
    if (!ctx_ || !ctx_->monitor_manager || !ctx_->monitor_manager->saveOverrides(&error)) {
        DBusMessage* reply = dbus_message_new_error(
            msg, "com.example.WeakNet.Error",
            error.empty() ? "failed to save monitor overrides" : error.c_str());
        if (reply) { dbus_connection_send(conn, reply, nullptr); dbus_message_unref(reply); }
        return false;
    }
    const char* result = "ok";
    DBusMessage* reply = dbus_message_new_method_return(msg);
    if (!reply) return false;
    DBusMessageIter iter;
    dbus_message_iter_init_append(reply, &iter);
    dbus_message_iter_append_basic(&iter, DBUS_TYPE_STRING, &result);
    dbus_connection_send(conn, reply, nullptr);
    dbus_connection_flush(conn);
    dbus_message_unref(reply);
    return true;
}

}  // namespace weaknet_dbus

